//! The action reference is generated from the code that parses action names.
//!
//! `docs/configuration/actions.md` lists every built-in action name, the args
//! each one reads, and its description — the names a keybinding's `"action"`,
//! a macro step in `init.ts` (`editor.defineMacro`) and `editor.executeActions`
//! accept. It is rendered from `Action::all_action_names()` and
//! `Action::action_arg_keys()`, both generated by the same macro as
//! `Action::from_str`, so this test fails when the page and the parser drift.
//!
//! Regenerate with:
//!
//! ```sh
//! UPDATE_DOCS=1 cargo test -p fresh-editor --test all_tests -- action_name_docs::
//! ```

use std::collections::HashMap;
use std::fs;
use std::path::PathBuf;

use crate::common::global_state::pin_config_globals;
use fresh::input::keybindings::{Action, KeybindingResolver};

fn doc_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../docs/configuration/actions.md")
}

/// The value each arg key is shown with in the examples. A new arg key has to
/// be added here, which is the point: the page can't silently document an arg
/// without saying what goes in it.
fn sample_value(arg_key: &str) -> &'static str {
    match arg_key {
        "char" => "x",
        "theme" => "dracula",
        "name" => "File",
        "map" => "emacs",
        "text" => "hello",
        other => panic!(
            "no sample value for action arg `{other}` — add one to `sample_value` in \
             tests/action_name_docs.rs"
        ),
    }
}

/// Escape text for a markdown table cell.
fn cell(s: &str) -> String {
    s.replace('|', "\\|")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
}

/// `{ key: "value", ... }` — the args object as written in `init.ts`.
fn args_literal(keys: &[&str]) -> String {
    let fields: Vec<String> = keys
        .iter()
        .map(|k| format!("{k}: \"{}\"", sample_value(k)))
        .collect();
    format!("{{ {} }}", fields.join(", "))
}

fn sample_args(keys: &[&str]) -> HashMap<String, serde_json::Value> {
    keys.iter()
        .map(|k| (k.to_string(), serde_json::Value::from(sample_value(k))))
        .collect()
}

fn render() -> String {
    let names = Action::all_action_names();
    let mut out = String::new();

    out.push_str(
        "<!-- Generated from the action tables in the source. Do not edit: change \
         `crates/fresh-editor/src/input/keybindings.rs`, then run \
         `UPDATE_DOCS=1 cargo test -p fresh-editor --test all_tests -- action_name_docs::`. -->\n\n",
    );
    out.push_str("# Actions\n\n");
    out.push_str(
        "Every built-in action, by the name Fresh reads it under. The same names are \
         used everywhere an action is written down:\n\n\
         - a keybinding's `\"action\"` in `config.json` (see [Keyboard](./keyboard.md));\n\
         - a macro step in [`init.ts`](./init.md) — what **Macro: Save to init.ts** writes \
         as `editor.defineMacro(...)`;\n\
         - a step passed to `editor.executeActions` from a plugin.\n\n",
    );

    out.push_str("## Step format\n\n");
    out.push_str(
        "In `init.ts` and plugins, each step is an object with the action's name, \
         an optional `count`, and `args` for the few actions that carry data:\n\n",
    );
    out.push_str("```typescript\n");
    out.push_str("{ action: \"move_word_right\" }                  // no args\n");
    out.push_str("{ action: \"move_down\", count: 3 }              // repeated 3 times\n");
    out.push_str("{ action: \"insert_char\", args: { char: \"x\" } } // with args\n");
    out.push_str("```\n\n");
    out.push_str(
        "In `config.json`, a keybinding takes the same `args` object next to its \
         `\"action\"`.\n\n",
    );
    out.push_str(
        "**A name that isn't listed here is treated as a plugin action** — the name of a \
         handler a plugin registered with `registerHandler` (or `init.ts` did). That is \
         what lets you bind keys to plugin commands, and it is also why a misspelled \
         built-in name raises no error: it becomes a plugin action nothing handles, \
         and does nothing when run.\n\n",
    );

    out.push_str("## Actions that take args\n\n");
    out.push_str("| Action | Args | Example |\n|---|---|---|\n");
    for name in &names {
        let keys = Action::action_arg_keys(name);
        if keys.is_empty() {
            continue;
        }
        let action = Action::from_str(name, &sample_args(keys))
            .unwrap_or_else(|| panic!("`{name}` did not parse from its sample args"));
        out.push_str(&format!(
            "| `{name}` | `{}` | {} |\n",
            args_literal(keys),
            cell(&KeybindingResolver::format_action(&action)),
        ));
    }
    out.push('\n');

    out.push_str("## All actions\n\n");
    out.push_str("| Action | Description |\n|---|---|\n");
    for name in &names {
        let keys = Action::action_arg_keys(name);
        let action = Action::from_str(name, &sample_args(keys))
            .unwrap_or_else(|| panic!("`{name}` did not parse"));
        let canonical = action.to_action_str();
        let mut description = cell(&KeybindingResolver::format_action(&action));
        if keys.is_empty() && canonical != *name {
            description = format!("Alias of `{canonical}`. {description}");
        }
        let args = if keys.is_empty() {
            String::new()
        } else {
            format!(" (args: `{}`)", args_literal(keys))
        };
        out.push_str(&format!("| `{name}` | {description}{args} |\n"));
    }
    out
}

#[test]
fn generated_action_docs_match_the_code() {
    // The descriptions come from the English catalog; hold the locale there.
    let _locale = pin_config_globals();
    fresh::i18n::set_locale("en");

    let path = doc_path();
    let expected = render();
    let current = fs::read_to_string(&path).unwrap_or_default();

    if current == expected {
        return;
    }

    if std::env::var_os("UPDATE_DOCS").is_some() {
        fs::write(&path, expected).unwrap();
        return;
    }

    if current.replace("\r\n", "\n") == expected.replace("\r\n", "\n") {
        panic!(
            "{} differs from the generated reference only in its line endings. This \
             checkout has CRLF where the repository stores LF; `.gitattributes` pins \
             the file, so refresh the working copy:\n  git rm --cached \
             docs/configuration/actions.md && git checkout -- docs/configuration/actions.md",
            path.display(),
        );
    }

    panic!(
        "{} is out of date with the action tables in `input/keybindings.rs`.\n\n\
         Regenerate:\n  UPDATE_DOCS=1 cargo test -p fresh-editor --test all_tests -- \
         action_name_docs::",
        path.display()
    );
}
